package com.nexustools.genericui.style.css

import com.nexustools.genericui.core.AbstractComponent

/**
 * Interface implemented by build-time precompiled SASS/CSS Kotlin stylesheet objects
 * generated by `compileGenericUiSass` (`GenericUiSassCompileTask`) or `SassKotlinPrecompiler`.
 *
 * Precompiled stylesheets construct their [CssStyleSheet] directly from pre-parsed [CssRule]
 * instances and `@keyframes` maps so zero SASS compilation or CSS text parsing occurs at runtime.
 */
interface PrecompiledStyleSheet {
    /** Logical name or source path of the stylesheet (e.g. `"style"`). */
    val name: String

    /** Precompiled, pre-sorted [CssStyleSheet] ready for immediate O(1) cached style resolution. */
    val styleSheet: CssStyleSheet

    /** Optional normalized CSS string representation (for web `<style>` injection or inspection). */
    val rawCss: String
        get() = ""

    /** Relative path to the compiled `.css` file generated for the Web target (e.g. `"style.css"`). */
    val cssResourcePath: String
        get() = "$name.css"

    /**
     * Applies this precompiled stylesheet to [component] and all of its descendants.
     */
    fun applyTo(component: AbstractComponent, viewportWidthPx: Int = 1280) {
        component.applyStyleSheet(styleSheet, viewportWidthPx)
    }
}
